import { useEffect, useId, useState, type ReactNode } from "react";
import { getAllowanceState } from "@/lib/usage/getAllowanceState";
import { AllowanceGauge } from "./AllowanceGauge";
import styles from "./usage.module.css";

type AllowanceCardProps = {
  title: string;
  remaining: number;
  total: number;
  sent: number;
  queued: number;
  unitText: string;
  resetUtcText?: ReactNode;
  resetLocalText?: ReactNode;
  used?: number;
  resetsAt?: string | null;
  period: "daily" | "monthly" | "rolling";
  unavailable?: boolean;
  followsBillingPeriod?: boolean;
};

function ResetPill({
  resetsAt,
  period,
  followsBillingPeriod,
}: Pick<AllowanceCardProps, "resetsAt" | "period" | "followsBillingPeriod">) {
  // The first client render matches the server; the countdown starts after hydration.
  const [now, setNow] = useState<number | null>(null);
  useEffect(() => {
    if (period !== "daily" || !resetsAt) return;
    const update = () => setNow(Date.now());
    const initial = window.setTimeout(update, 0);
    const timer = window.setInterval(update, 60_000);
    return () => {
      window.clearTimeout(initial);
      window.clearInterval(timer);
    };
  }, [period, resetsAt]);
  let text = followsBillingPeriod
    ? "Follows your billing period"
    : "Reset time unavailable";
  if (resetsAt) {
    const reset = new Date(resetsAt);
    if (period === "daily" && now !== null) {
      const minutes = Math.max(0, Math.ceil((reset.getTime() - now) / 60_000));
      text = `Resets in ${Math.floor(minutes / 60)}h ${minutes % 60}m`;
    } else {
      text = `Resets ${new Intl.DateTimeFormat("en-US", { timeZone: "UTC", month: "short", day: "numeric" }).format(reset)}`;
    }
  }
  return (
    <span
      className={`${styles.resetPill} inline-flex py-[5px] px-3 rounded-full text-[12.5px] font-bold text-[var(--usage-yellow)] [background:color-mix(in_srgb,_var(--usage-yellow)_12%,_transparent)]`}
    >
      {text}
    </span>
  );
}

export function AllowanceCard({
  title,
  remaining,
  total,
  sent,
  queued,
  used = sent + queued,
  unitText,
  resetUtcText,
  resetLocalText,
  resetsAt,
  period,
  unavailable = false,
  followsBillingPeriod = false,
}: AllowanceCardProps) {
  const titleId = useId();
  const state = getAllowanceState({ remaining, total, queued });
  const depleted = state === "empty" || state === "reserved";
  const legacy = period === "rolling";
  // Clamp only the drawing, keeping all provider counts intact after plan changes.
  const sentPercent =
    total > 0 ? Math.max(0, Math.min(100, (sent / total) * 100)) : 0;
  const queuedPercent =
    total > 0
      ? Math.max(0, Math.min(100 - sentPercent, (queued / total) * 100))
      : 0;
  const label =
    state === "healthy"
      ? "emails remaining"
      : state === "low"
        ? "Running low"
        : state === "reserved"
          ? "All reserved"
          : "No emails left";
  return (
    <section
      className={`hover-card backdrop-blur-xs workspace-mono:backdrop-blur-none [background:var(--usage-card)] [border:1px_solid_var(--usage-line)] rounded-[var(--appearance-radius,_24px)] usage-allowance p-6.5 min-w-0 [@media(max-width:_480px)]:p-5.5 ${depleted && !unavailable ? `workspace-mono:border-[var(--usage-warning-line)] border-[color-mix(in_srgb,_var(--usage-yellow)_40%,_transparent)]` : ""}`}
      aria-labelledby={titleId}
      data-allowance-state={unavailable ? "unavailable" : state}
    >
      <h3 id={titleId} className="text-[19px] font-bold tracking-[-0.02em]">
        {title}
      </h3>
      {unavailable ? (
        <div className="py-7">
          <strong>{title} unavailable</strong>
          {followsBillingPeriod && (
            <p className="mt-2 text-[var(--usage-muted)] text-[14px]">
              Follows your billing period
            </p>
          )}
          <p className="mt-2 text-[var(--usage-muted)] text-[14px]">
            Waiting for verified subscription billing dates. Sending is paused
            until this period is confirmed.
          </p>
        </div>
      ) : (
        <>
          <div className="flex items-center gap-5.5 [margin:16px_0_20px] [@media(max-width:_820px)]:flex-col [@media(max-width:_820px)]:items-start">
            <AllowanceGauge remaining={remaining} total={total} state={state} />
            <div className="min-w-0">
              <strong
                className={
                  state !== "healthy" ? "text-[var(--usage-yellow)]" : undefined
                }
              >
                {label}
              </strong>
              <p className="text-[var(--usage-muted)] text-[14px]">
                {state === "reserved"
                  ? "Queued emails are still waiting to send."
                  : `of ${unitText}`}
              </p>
              {depleted && !legacy && (
                <div className="flex items-center flex-wrap [gap:6px_12px] mt-3.5">
                  <ResetPill
                    resetsAt={resetsAt}
                    period={period}
                    followsBillingPeriod={followsBillingPeriod}
                  />
                </div>
              )}
            </div>
          </div>
          <div
            className={`workspace-mono:bg-[var(--usage-track)] workspace-mono:rounded-[var(--usage-bar-radius)] h-2 rounded-[var(--appearance-radius,_5px)] [background:var(--usage-line)] flex overflow-hidden`}
            role="img"
            aria-label={
              legacy
                ? `${used} used or queued of ${total}; ${remaining} remaining`
                : `${sent} sent, ${queued} queued of ${total}; ${used} used; ${remaining} remaining`
            }
          >
            <span
              className="h-full bg-[var(--usage-green)] workspace-mono:bg-[var(--usage-accent)]"
              style={{ width: `${sentPercent}%` }}
            />
            <span
              className="h-full bg-[var(--usage-queued-color)]"
              style={{ width: `${queuedPercent}%` }}
            />
          </div>
          <div
            className={`flex [gap:8px_16px] flex-wrap items-center mt-3 text-[13px] text-[var(--usage-muted)]`}
          >
            {legacy ? (
              <span>{used} used or queued</span>
            ) : (
              <>
                <span>
                  <span
                    aria-hidden="true"
                    className="inline-block w-2 h-2 rounded-full mr-[7px] bg-[var(--usage-green)] workspace-mono:bg-[var(--usage-accent)]"
                  />
                  {sent} sent
                </span>
                <span>
                  <span
                    aria-hidden="true"
                    className="inline-block w-2 h-2 rounded-full mr-[7px] bg-[var(--usage-queued-color)]"
                  />
                  {queued} queued
                </span>
              </>
            )}
            <em className="ml-auto not-italic">
              {used} used of {total}
            </em>
          </div>
          {used > total && (
            <p className="text-[13px] text-[var(--usage-yellow)] mt-3">
              {used - total} over the current allowance. Your usage is retained
              after a plan change.
            </p>
          )}
          <div
            className={`mt-5 pt-4 border-t border-dotted border-separator text-[13.5px] text-[var(--usage-muted)]`}
          >
            {legacy ? (
              <p>
                Capacity returns as sends leave the rolling 24-hour window or
                unused queue reservations are released.
              </p>
            ) : resetUtcText ? (
              <>
                <strong className="text-[var(--usage-text)] font-semibold block workspace-mono:font-bold">
                  {resetUtcText}
                </strong>
                {resetLocalText && <p className="mt-1">{resetLocalText}</p>}
              </>
            ) : (
              <>
                <strong className="text-[var(--usage-text)] font-semibold block workspace-mono:font-bold">
                  {followsBillingPeriod
                    ? "Follows your billing period"
                    : "Reset time unavailable"}
                </strong>
                {!followsBillingPeriod && (
                  <p className="mt-1">
                    Sending will resume once the period is verified.
                  </p>
                )}
              </>
            )}
          </div>
        </>
      )}
    </section>
  );
}
